def two_sum(num_list, target_value):
    for i in range(len(num_list)):
        for j in range(i + 1, len(num_list)):
            if num_list[j] == target_value - num_list[i]:
                return [i, j]

num_list = [2, 7, 11, 15]
target_value = 9

result = two_sum(num_list, target_value)
print(result)    # [0, 1]

def two_sum(num_list, target_value):

    dictionary = {}
    for index, value in enumerate(num_list): 

        # 将num_list的元素添加到字典
        # 元素为键，索引为值。
        dictionary[value] = index

    for i in range(len(num_list)):
        complement = target_value - num_list[i]

        # 检查字典中是否存在互补元素
        if complement in dictionary and dictionary[complement] != i:

            # 返回元素索引与补数索引
            return [i, dictionary[complement]]

num_list = [2, 7, 11, 15]
target_value = 9

result = two_sum(num_list, target_value)
print(result)    # [0, 1]
